32	const BASE_PREMIUMS: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	const PROCESSING_FEE = 5;
42	
43	const WHOLE_PERCENT = 100;
44	
45	/**
46	 * Surcharges multiply before dividing, so the arithmetic stays exact.
47	 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
48	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
49	 * instead of 115 G.
50	 */
51	const addSurcharge = (amount: number, surchargePercent: number): number =>
52	  (amount * (WHOLE_PERCENT + surchargePercent)) / WHOLE_PERCENT;
53	
54	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
55	
56	/** All rounding is in the MHPCO's favor — always up. */
57	const roundInMHPCOsFavor = Math.ceil;
58	
59	const BUILDING_BLOCK_SIZE = 3;
60	const BUILDING_BLOCK_PREMIUM = 60;
61	
62	/** Only items of one and the same kind group into a block. */
63	const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
64	  first !== undefined && rest.every((item) => item.type === first.type);
65	
66	/**
67	 * How many flat-rate blocks this list forms. A mixed list forms none — only
68	 * alike items group — and so does any list too short to fill one block.
69	 */
70	const countCompleteBlocks = (items: InsuredItem[]): number =>
71	  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
72	
73	const CURSED_SURCHARGE_PERCENT = 50;
74	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
75	const HIGH_ENCHANTMENT_LEVEL = 5;
76	
77	/** A risk rule contributes its percent only when the item trips it. */
78	const percentWhen = (applies: boolean, percent: number): number =>
79	  applies ? percent : 0;
80	
81	const isHighlyEnchanted = (item: InsuredItem): boolean =>
82	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
83	
84	/** Risk surcharges add to the base premium; they do not compound. */
85	const riskSurchargePercentFor = (item: InsuredItem): number =>
86	  percentWhen(item.cursed === true, CURSED_SURCHARGE_PERCENT) +
87	  percentWhen(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
88	
89	/** An item's list price with its own risk surcharges applied. */
90	const riskAdjustedPremiumFor = (item: InsuredItem): number =>
91	  addSurcharge(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));
92	
93	const sumRiskAdjustedPremiums = (items: InsuredItem[]): number =>
94	  items.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0);
95	
96	/**
97	 * Prices an item list: alike items are grouped into building blocks sold at a
98	 * flat rate, and whatever is left over is priced item by item, each at its own
99	 * risk-adjusted premium.
100	 */
101	const priceItems = (items: InsuredItem[]): number => {
102	  const blocks = countCompleteBlocks(items);
103	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
104	
105	  return blocks * BUILDING_BLOCK_PREMIUM + sumRiskAdjustedPremiums(leftovers);
106	};
107	
108	/**
109	 * The premium pipeline, in the order the spec states it: price the items,
110	 * apply surcharges, round, then add the processing fee last.
111	 */
112	const LOYALTY_DISCOUNT_PERCENT = 20;
113	const LOYALTY_YEARS = 2;
114	
115	const isLongStanding = (customer: Customer): boolean =>
116	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
117	
118	const quotePremium = (
119	  items: InsuredItem[],
120	  customer: Customer,
121	): QuoteResult => {
122	  const discounted = addSurcharge(
123	    priceItems(items),
124	    -percentWhen(isLongStanding(customer), LOYALTY_DISCOUNT_PERCENT),
125	  );
126	  const surcharged = addSurcharge(discounted, FIRST_INSURANCE_SURCHARGE_PERCENT);
127	
128	  return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
129	};
130	
131	export const runScenario = (scenario: Scenario): ScenarioResults => ({
132	  results: scenario.steps.map((step) =>
133	    quotePremium(step.items ?? [], scenario.customer),
134	  ),
135	});
