/** A discount is a negative adjustment — long-standing customers pay 20% less. */
const LOYALTY_DISCOUNT_PERCENT = -20;
const LOYALTY_YEARS = 2;

const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

/**
 * What the customer's own standing adds to, or takes off, the item price —
 * as a single signed percentage.
 */
const customerPercentFor = (customer: Customer): number =>
  percentWhen(isLongStanding(customer), LOYALTY_DISCOUNT_PERCENT) +
  FIRST_INSURANCE_SURCHARGE_PERCENT;

/**
 * The premium pipeline, in the order the spec states it: price the items,
 * apply the customer's modifiers, round, then add the processing fee last.
 */
const quotePremium = (
  items: InsuredItem[],
  customer: Customer,
): QuoteResult => {
  const adjusted = adjustByPercent(
    priceItems(items),
    customerPercentFor(customer),
  );

  return { premium: roundInMHPCOsFavor(adjusted) + PROCESSING_FEE };
};

